def transform(grid):
    n = len(grid[0])
    center = next(i for i, v in enumerate(grid[0]) if v == 2)
    out = [[0] * n for _ in range(n)]
    for r in range(n):
        if r <= center:
            for c in (center-r, center+r):
                out[r][c] = 2
        if r >= 3:
            for c in range(n):
                if (c-r) % 4 == 2 and out[r][c] == 0:
                    if r > center or center-r <= c <= center+r:
                        out[r][c] = 1
    return out
